```c
// task.c
#include "task.h"
#include <unistd.h>
static progress_cb g_cb;
static void* g_user;
int start_task_async(progress_cb cb, void* user){
    g_cb = cb; g_user = user;
    for (int i = 1; i <= 4; ++i){
